`,e.jsxs(a.p,{children:["En 3.8.0 cada servicio tenía su propia base de datos. El backend de 4.0.0 se conecta a una única base de datos PostgreSQL llamada ",e.jsx(a.code,{children:"pki"})," y aísla cada servicio en un esquema: ",e.jsx(a.code,{children:"kms"}),", ",e.jsx(a.code,{children:"ca"}),", ",e.jsx(a.code,{children:"va"}),", ",e.jsx(a.code,{children:"devicemanager"}),", ",e.jsx(a.code,{children:"dmsmanager"})," y ",e.jsx(a.code,{children:"alerts"}),". El servicio ",e.jsx(a.code,{children:"authz"})," guarda sus principales, permisos y políticas en una base de datos ",e.jsx(a.code,{children:"authz"})," separada (el monolítico de desarrollo usa en su lugar un esquema ",e.jsx(a.code,{children:"authz"})," dentro de ",e.jsx(a.code,{children:"pki"}),"), y WFX conserva su propia base ",e.jsx(a.code,{children:"wfx"}),"."]}),`
